sp_widget.client_script:
function loginCtrl($scope, $http, $window, $location, glideUserSession, glideSystemProperties, spUtil) {

    var c = this;

    c.remember_me = c.data.forgetMe ? false : c.data.rememberMeDefault;
    c.data.url_suffix = $scope.portal ? $scope.portal.url_suffix : "";
    c.masked = true;

    /* =========================================
       SIGNUP WIZARD CONTROLS & STATE
       ========================================= */

    c.activeTab = 'login';
    c.signupStep = 1;
    c.signupSubmitting = false;

    c.signupForm = {
        role: '',
        studentName: '',
        email: '',
        registerNumber: '',
        gender: '',
        mobile: '',
        altMobile: '',
        password: '',
        confirmPassword: '',
        collegeName: '',
        branch: '',
        cgpa: '',
        passingYear: '',
        backlogs: '',
        skills: [],
        git: '',
        linkedin: ''
    };

    /* =========================================
       SIGNUP SKILLS
       ========================================= */

    c.signupSkillDropdownOpen = false;
    c.signupSkillSearch = '';

    c.toggleSignupSkillDropdown = function() {

        c.signupSkillDropdownOpen =
            !c.signupSkillDropdownOpen;

    };

    c.isSignupSkillSelected = function(skillName) {

        return (
            angular.isArray(c.signupForm.skills) &&
            c.signupForm.skills.indexOf(skillName) !== -1
        );

    };

    c.toggleSignupSkill = function(skill, $event) {

        if ($event) {
            $event.stopPropagation();
        }

        if (!angular.isArray(c.signupForm.skills)) {
            c.signupForm.skills = [];
        }

        var index =
            c.signupForm.skills.indexOf(
                skill.name
            );

        if (index === -1) {

            c.signupForm.skills.push(
                skill.name
            );

        } else {

            c.signupForm.skills.splice(
                index,
                1
            );
        }

    };

    c.removeSignupSkill = function(skill, $event) {

        if ($event) {
            $event.stopPropagation();
        }

        if (!angular.isArray(c.signupForm.skills)) {
            return;
        }

        var index =
            c.signupForm.skills.indexOf(
                skill
            );

        if (index !== -1) {

            c.signupForm.skills.splice(
                index,
                1
            );
        }

    };

    var strongPwdRegex =
        /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W_]).{8,}$/;

    c.toggleTab = function(tabName) {

        c.activeTab = tabName;
        c.signupError = null;
        c.signupSuccess = null;

    };

    // Student & Coordinator get the full 3-step wizard; Placement Officer & HR get the simple form
    c.isMultiStepRole = function() {

        return c.signupForm.role === 'student' ||
               c.signupForm.role === 'coordinator';

    };

    c.onRoleChange = function() {

        c.signupStep = 1;
        c.signupError = null;

        c.signupSkillDropdownOpen = false;
        c.signupSkillSearch = '';

    };

    c.setStep = function(step) {

        if (
            step < c.signupStep ||
            c.validateStep(c.signupStep)
        ) {

            c.signupStep = step;
            c.signupError = null;
        }

    };

    c.nextStep = function() {

        if (c.validateStep(c.signupStep)) {

            c.signupError = null;

            if (c.signupStep < 3) {
                c.signupStep++;
            }
        }

    };

    c.prevStep = function() {

        c.signupError = null;

        if (c.signupStep > 1) {
            c.signupStep--;
        }

    };

    // Step-by-step UI validation for the multi-step (student/coordinator) wizard
    c.validateStep = function(step) {

        var f = c.signupForm;

        if (step === 1) {

            if (
                !f.studentName ||
                !f.email ||
                !f.registerNumber ||
                !f.mobile
            ) {

                c.signupError =
                    "Please fill in all required fields in Step 1.";

                return false;
            }

            if (!f.password || !f.confirmPassword) {

                c.signupError =
                    "Please enter and confirm your password.";

                return false;
            }

            if (f.password !== f.confirmPassword) {

                c.signupError =
                    "Password and Confirm Password do not match.";

                return false;
            }

            if (!strongPwdRegex.test(f.password)) {

                c.signupError =
                    "Password must be 8+ characters with uppercase, lowercase, a number, and a special character.";

                return false;
            }

        } else if (step === 2) {

            if (
                !f.collegeName ||
                !f.branch ||
                f.cgpa === '' ||
                f.passingYear === '' ||
                f.backlogs === ''
            ) {

                c.signupError =
                    "Please fill in all required fields in Step 2.";

                return false;
            }

        } else if (step === 3) {

            if (
                !angular.isArray(f.skills) ||
                f.skills.length === 0
            ) {

                c.signupError =
                    "Please select at least one technical skill.";

                return false;
            }
        }

        return true;
    };

    // Validation for the simple form (Placement Officer / HR)
    c.validateSimpleForm = function() {

        var f = c.signupForm;

        if (
            !f.studentName ||
            !f.email ||
            !f.password ||
            !f.confirmPassword
        ) {

            c.signupError =
                "Please fill in all required fields.";

            return false;
        }

        if (f.password !== f.confirmPassword) {

            c.signupError =
                "Password and Confirm Password do not match.";

            return false;
        }

        if (!strongPwdRegex.test(f.password)) {

            c.signupError =
                "Password must be 8+ characters with uppercase, lowercase, a number, and a special character.";

            return false;
        }

        return true;
    };

    /* =========================================
       SIGNUP SUBMISSION HANDLER
       ========================================= */

    c.signup = function() {

        if (!c.signupForm.role) {

            c.signupError =
                "Please select a role to register.";

            return;
        }

        if (c.isMultiStepRole()) {

            if (!c.validateStep(3))
                return;

        } else {

            if (!c.validateSimpleForm())
                return;
        }

        c.signupSubmitting = true;
        c.signupError = null;
        c.signupSuccess = null;

        /* =========================================
           KEEP UI AS ARRAY
           SEND SKILLS AS STRING TO BACKEND
           ========================================= */

        var signupPayload =
            angular.copy(c.signupForm);

        signupPayload.skills =
            angular.isArray(
                signupPayload.skills
            )
                ? signupPayload.skills.join(', ')
                : (
                    signupPayload.skills ||
                    ''
                );

        c.server.get({

            action: 'signup_student',

            signupForm:
                signupPayload

        }).then(function(response) {

            c.signupSubmitting = false;

            if (response.data.signupSuccess) {

                c.signupSuccess =
                    response.data.signupSuccessMessage;

                if (response.data.pendingApproval) {

                    // No redirect: go back to the login side after a short pause
                    setTimeout(function() {

                        $scope.$applyAsync(function() {

                            c.signupSuccess = null;

                            c.toggleTab('login');

                            c.signupStep = 1;

                            c.signupSkillDropdownOpen = false;
                            c.signupSkillSearch = '';

                            c.signupForm = {

                                role: '',
                                studentName: '',
                                email: '',
                                registerNumber: '',
                                gender: '',
                                mobile: '',
                                altMobile: '',
                                password: '',
                                confirmPassword: '',
                                collegeName: '',
                                branch: '',
                                cgpa: '',
                                passingYear: '',
                                backlogs: [],
                                skills: [],
                                git: '',
                                linkedin: ''
                            };

                        });

                    }, 3500);

                } else {

                    setTimeout(function() {

                        var targetUrl =
                            response.data.redirectUrl ||
                            '/nexora?id=dashboard';

                        $window.location.href =
                            targetUrl;

                    }, 1200);
                }

            } else {

                // ...existing else branch unchanged

                c.signupError =
                    response.data.signupError ||
                    'Registration failed.';

                // Send the student/coordinator back to whichever step likely caused the error
                if (c.isMultiStepRole()) {

                    var errMsg =
                        (c.signupError || '')
                        .toLowerCase();

                    if (
                        errMsg.indexOf('email') !== -1 ||
                        errMsg.indexOf('register number') !== -1 ||
                        errMsg.indexOf('password') !== -1
                    ) {

                        c.signupStep = 1;

                    } else if (
                        errMsg.indexOf('college') !== -1 ||
                        errMsg.indexOf('branch') !== -1 ||
                        errMsg.indexOf('cgpa') !== -1
                    ) {

                        c.signupStep = 2;
                    }
                }
            }

        }, function() {

            c.signupSubmitting = false;

            c.signupError =
                'Server communication error. Please try again.';

        });
    };

    /* =========================================
       SSO AUTO REDIRECT
       ========================================= */

    if (
        !c.data.is_logged_in &&
        c.data.multisso_enabled &&
        c.data.default_idp
    ) {

        var pageId =
            $location.search().id ||
            $scope.page.id;

        var isLoginPage =
            ($scope.portal.login_page_dv == pageId) ||
            ('login' == pageId);

        c.server.get({

            action: "set_sso_destination",

            pageURI:
                isLoginPage
                    ? null
                    : $location.url()

        }).then(function() {

            $window.location =
                "/login_with_sso.do?glide_sso_id=" +
                c.data.default_idp;

        });

    }

    else if (
        !c.data.is_logged_in &&
        c.data.certAuthRedirect &&
        c.data.cert_based_auth &&
        c.data.certHeader == "true"
    ) {

        login(null, null, true);

    }

    /* =========================================
       LOGIN
       ========================================= */

    c.login = function(username, password, isCertLogin) {

        login(
            username,
            password,
            isCertLogin
        );

    };

    function login(username, password, isCertLogin) {

        var url =
            spUtil.getURL({
                sysparm_type: 'view_form.login'
            });

        var pageId =
            $location.search().id ||
            $scope.page.id;

        var isLoginPage =
            ($scope.portal.login_page_dv == pageId) ||
            ('login' == pageId);

        return $http({

            method: 'post',

            url: url,

            data: $.param({

                'sysparm_type': 'login',

                'ni.nolog.user_password': true,

                'remember_me':
                    !!c.remember_me
                        ? true
                        : false,

                'user_name':
                    username,

                'user_password':
                    password,

                'get_redirect_url':
                    true,

                'is_direct_redirect':
                    true,

                'sysparm_goto_url':
                    isLoginPage
                        ? null
                        : $location.url(),

                'mfa_redirect_url':
                    isLoginPage
                        ? null
                        : c.data.pageURI,

                'cert_login':
                    !!isCertLogin

            }),

            headers: {

                'Content-Type':
                    'application/x-www-form-urlencoded'

            }

        }).then(function(response) {

            if (!response.data) {

                c.message =
                    $scope.data.errorMsg;

                return;

            }

            /* LOGIN SUCCESS */

            if (
                response.data.status ==
                'success'
            ) {

                if (
                    c.data.multiFactorAuthEnabled
                ) {

                    if (
                        response.data.session_token
                    ) {

                        window.g_ck =
                            response.data.session_token;

                    }

                    c.server.get({

                        action:
                            "multi_factor_auth_setup",

                        directTo:
                            response.data.redirect_url

                    }).then(

                        handleLoginResponse.bind(response),

                        handleLoginResponse.bind(response)

                    );

                }

                else {

                    handleLoginResponse.call(
                        response
                    );

                }

            }

            /* MFA */

            else if (
                response.data.status ==
                'mfa_code_required'
            ) {

                $window.location =
                    '/validate_multifactor_auth_code.do';

            }

            /* INVALID LOGIN */

            else {

                c.message =
                    response.data.message;

                c.password = "";

                c.username = "";

                angular
                    .element("#username")
                    .focus();

            }

        }, function errorCallback(response) {

            c.message =
                $scope.data.errorMsg;

        });

    }

    /* =========================================
       OIDC LOGIN
       ========================================= */

    c.oidcLogin = function(idProvider) {

        var pageId =
            $location.search().id ||
            $scope.page.id;

        var isLoginPage =
            $scope.portal.login_page_dv ==
            pageId;

        c.server.get({

            action:
                "set_sso_destination",

            pageURI:
                isLoginPage
                    ? null
                    : $location.url()

        }).then(function() {

            $window.location =
                "/login_with_sso.do?glide_sso_id=" +
                idProvider;

        });

    };

    /* =========================================
       EXTERNAL LOGIN
       ========================================= */

    c.externalLogin = function() {

        var pageId =
            $location.search().id ||
            $scope.page.id;

        var isLoginPage =
            ($scope.portal.login_page_dv == pageId) ||
            ('login' == pageId);

        c.server.get({

            action:
                "set_sso_destination",

            pageURI:
                isLoginPage
                    ? null
                    : $location.url()

        }).then(function() {

            glideSystemProperties.set(
                "glide.authenticate.multisso.enabled",
                true
            );

            glideUserSession
                .getSsoRedirectUrlForUsername(
                    c.username
                )
                .then(function(url) {

                    $window.location =
                        url;

                }, function(err) {

                    spUtil.addErrorMessage(
                        $scope.data.errorMsg2
                    );

                });

        });

    };

    /* =========================================
       LOGIN RESPONSE
       ========================================= */

    function handleLoginResponse() {

        c.success =
            this.data.message;

        $window.location =
            this.data.redirect_url;

        if (
            $window.location.hash.length > 0
        ) {

            $window.location.reload();

        }

    }

    /* =========================================
       EXTERNAL LOGIN MODE
       ========================================= */

    c.setExternalLogin = function(newVal) {

        c.externalLoginMode =
            newVal;

        if (!newVal) {

            c.masked = true;

        }

    };

    /* =========================================
       PASSWORD EYE (LOGIN FORM — single field, unchanged)
       ========================================= */

    c.renderMaskIcon = function() {

        var passwordEle =
            document.getElementById("password");

        var maskEle =
            document.getElementById("mask_icon");

        var eyeEle =
            document.getElementById("password_eye");

        if (!passwordEle || !maskEle) {

            return;

        }

        var isPasswordType =
            passwordEle.type === "password";

        /* SHOW PASSWORD */

        if (isPasswordType) {

            passwordEle.type = "text";

            if (eyeEle) {

                eyeEle.classList.remove(
                    "fa-eye"
                );

                eyeEle.classList.add(
                    "fa-eye-slash"
                );

            }

            maskEle.setAttribute(
                "aria-label",
                "Hide password"
            );

            maskEle.setAttribute(
                "title",
                "Hide password"
            );

        }

        /* HIDE PASSWORD */

        else {

            passwordEle.type = "password";

            if (eyeEle) {

                eyeEle.classList.remove(
                    "fa-eye-slash"
                );

                eyeEle.classList.add(
                    "fa-eye"
                );

            }

            maskEle.setAttribute(
                "aria-label",
                "Show password"
            );

            maskEle.setAttribute(
                "title",
                "Show password"
            );

        }

    };

    /* =========================================
       PASSWORD EYE (SIGNUP FORM — generic, works for any field id)
       ========================================= */

    c.togglePwd = function(fieldId) {

        var inputEle =
            document.getElementById(fieldId);

        var eyeEle =
            document.getElementById(
                fieldId + '_eye'
            );

        if (!inputEle) {
            return;
        }

        var isPasswordType =
            inputEle.type === 'password';

        if (isPasswordType) {

            inputEle.type = 'text';

            if (eyeEle) {

                eyeEle.classList.remove(
                    'fa-eye'
                );

                eyeEle.classList.add(
                    'fa-eye-slash'
                );
            }

        } else {

            inputEle.type = 'password';

            if (eyeEle) {

                eyeEle.classList.remove(
                    'fa-eye-slash'
                );

                eyeEle.classList.add(
                    'fa-eye'
                );
            }
        }

    };

};

sp_widget.css:
/* =========================================
   1. SERVICENOW PORTAL CONTAINER RESETS
   ========================================= */

#page-wrapper,
.page,
.sp-page-container,
.container-fluid,
.container,
.row,
.col-xs-12 {
    padding: 0 !important;
    margin: 0 !important;
    max-width: 100% !important;
    width: 100% !important;
}

/* =========================================
   2. FULLSCREEN PAGE WRAPPER
   ========================================= */

.nx-login-page {
    position: fixed !important;
    top: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    left: 0 !important;

    width: 100vw !important;
    height: 100vh !important;
    min-height: 100vh !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #182a3e;
    font-family: "Poppins", "Segoe UI", Arial, sans-serif;
    overflow: hidden;
    z-index: 99999;
}

.nx-login-container {
    display: flex !important;
    flex-direction: row !important;

    width: 100% !important;
    height: 100vh !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #182a3e;
}

/* =========================================
   3. HERO SECTION (LEFT)
   ========================================= */

.nx-login-hero {
    position: relative;
    width: 44%;
    height: 100vh;

    background-image: url("https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=1400&q=85");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;

    clip-path: polygon(
        0 0,
        100% 0,
        84% 100%,
        0 100%
    );

    overflow: hidden;
}

.nx-hero-overlay {
    position: absolute;
    inset: 0;

    background: linear-gradient(
        135deg,
        rgba(24, 42, 62, 0.92),
        rgba(24, 42, 62, 0.58)
    );
}

.nx-hero-content {
    position: relative;
    z-index: 2;

    display: flex;
    flex-direction: column;
    justify-content: space-between;

    height: 100%;
    padding: 55px 70px 65px;
    box-sizing: border-box;
}

.nx-hero-brand {
    color: #ffffff;
    font-size: 28px;
    font-weight: 800;
    letter-spacing: -0.5px;

    span {
        color: #f27457;
    }
}

.nx-hero-bottom {
    max-width: 430px;

    .nx-hero-kicker {
        display: inline-block;
        margin-bottom: 18px;
        color: rgba(255, 255, 255, 0.7);
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 2px;
    }

    h1 {
        margin: 0;
        color: #ffffff;
        font-size: clamp(38px, 4vw, 58px);
        font-weight: 800;
        line-height: 1.08;
        letter-spacing: -1.5px;
    }

    p {
        margin: 22px 0 0;
        color: rgba(255, 255, 255, 0.72);
        font-size: 14px;
        line-height: 1.7;
    }
}

/* =========================================
   4. RIGHT SECTION & FLIP CARD
   ========================================= */

.nx-login-form-section {
    flex: 1;
    height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #182a3e;
    color: #ffffff;
    padding: 0 !important;
    perspective: 1200px;
}

.nx-flip-card {
    width: 100%;
    max-width: 520px;
    height: 600px;
}

.nx-flip-inner {
    position: relative;
    width: 100%;
    height: 100%;
    transition: transform 0.8s cubic-bezier(0.4, 0, 0.2, 1);
    transform-style: preserve-3d;
}

.nx-flip-card.nx-flipped .nx-flip-inner {
    transform: rotateY(180deg);
}

.nx-flip-face {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
}

.nx-flip-front {
    z-index: 2;
    transform: rotateY(0deg);
}

.nx-flip-back {
    transform: rotateY(180deg);
}

.nx-login-inner {
    width: 100%;
    padding: 30px 40px;
    box-sizing: border-box;
}

/* Headers & Messaging */
.nx-login-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 25px;
}

.nx-brand {
    color: #ffffff;
    font-size: 26px;
    font-weight: 800;
    letter-spacing: -0.5px;

    span {
        color: #f27457;
    }
}

.nx-external-link a {
    color: #f27457 !important;
    font-size: 12px;
    font-weight: 600;
    text-decoration: none;

    &:hover {
        text-decoration: underline;
    }
}

.nx-welcome {
    margin-bottom: 20px;

    .nx-kicker {
        display: block;
        margin-bottom: 6px;
        color: #f27457;
        font-size: 10px;
        font-weight: 700;
        letter-spacing: 1.5px;
    }

    h2 {
        margin: 0;
        color: #ffffff;
        font-size: 28px;
        font-weight: 750;
        line-height: 1.2;
    }

    p {
        margin: 6px 0 0;
        color: rgba(255, 255, 255, 0.58);
        font-size: 12px;
    }
}

/* =========================================
   5. STEPPER WIZARD (SIGN UP)
   ========================================= */

.nx-stepper {
    display: flex;
    align-items: center;
    margin-bottom: 20px;
}

.nx-step {
    display: flex;
    align-items: center;
    gap: 6px;
    cursor: pointer;
    opacity: 0.5;
    transition: opacity 0.2s ease;

    &.active, &.completed {
        opacity: 1;
    }

    .nx-step-number {
        width: 22px;
        height: 22px;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.15);
        color: #ffffff;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 11px;
        font-weight: 700;
    }

    &.active .nx-step-number {
        background: #f27457;
        color: #ffffff;
    }

    &.completed .nx-step-number {
        background: #10b981;
        color: #ffffff;
    }

    .nx-step-label {
        color: rgba(255, 255, 255, 0.9);
        font-size: 11px;
        font-weight: 600;
    }
}

.nx-step-line {
    flex: 1;
    height: 2px;
    background: rgba(255, 255, 255, 0.15);
    margin: 0 8px;

    &.active {
        background: #f27457;
    }
}

.nx-signup-slider {
    overflow: hidden;
    width: 100%;
}

.nx-signup-track {
    display: flex;
    width: 300%;
    transition: transform 0.35s ease-in-out;
}

.nx-signup-tab {
    width: 33.3333%;
    flex-shrink: 0;
    padding: 0 2px;
    box-sizing: border-box;
}

/* Standalone simple-role form (Placement Officer / HR) — NOT part of the
   slider track, so it must NOT inherit the 33.3333% tab width above */
.nx-simple-form {
    width: 100%;
    box-sizing: border-box;
}

/* =========================================
   6. FORM CONTROLS & INPUTS
   ========================================= */

.nx-login-form {
    width: 100%;
}

.nx-form-row {
