/* =========================================
   1. SERVICENOW PORTAL CONTAINER RESETS
   ========================================= */

#page-wrapper,
.page,
.sp-page-container,
.container-fluid,
.container,
.row,
.col-xs-12 {
    padding: 0 !important;
    margin: 0 !important;
    max-width: 100% !important;
    width: 100% !important;
}

/* =========================================
   2. FULLSCREEN PAGE WRAPPER
   ========================================= */

.nx-login-page {
    position: fixed !important;
    top: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    left: 0 !important;

    width: 100vw !important;
    height: 100vh !important;
    min-height: 100vh !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #182a3e;
    font-family: "Poppins", "Segoe UI", Arial, sans-serif;
    overflow: hidden;
    z-index: 99999;
}

.nx-login-container {
    display: flex !important;
    flex-direction: row !important;

    width: 100% !important;
    height: 100vh !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #182a3e;
}

/* =========================================
   3. HERO SECTION (LEFT)
   ========================================= */

.nx-login-hero {
    position: relative;
    width: 44%;
    height: 100vh;

    background-image: url("https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=1400&q=85");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;

    clip-path: polygon(
        0 0,
        100% 0,
        84% 100%,
        0 100%
    );

    overflow: hidden;
}

.nx-hero-overlay {
    position: absolute;
    inset: 0;

    background: linear-gradient(
        135deg,
        rgba(24, 42, 62, 0.92),
        rgba(24, 42, 62, 0.58)
    );
}

.nx-hero-content {
    position: relative;
    z-index: 2;

    display: flex;
    flex-direction: column;
    justify-content: space-between;

    height: 100%;
    padding: 55px 70px 65px;
    box-sizing: border-box;
}

.nx-hero-brand {
    color: #ffffff;
    font-size: 28px;
    font-weight: 800;
    letter-spacing: -0.5px;

    span {
        color: #f27457;
    }
}

.nx-hero-bottom {
    max-width: 430px;

    .nx-hero-kicker {
        display: inline-block;
        margin-bottom: 18px;
        color: rgba(255, 255, 255, 0.7);
        font-size: 11px;
        font-weight: 700;
        letter-spacing: 2px;
    }

    h1 {
        margin: 0;
        color: #ffffff;
        font-size: clamp(38px, 4vw, 58px);
        font-weight: 800;
        line-height: 1.08;
        letter-spacing: -1.5px;
    }

    p {
        margin: 22px 0 0;
        color: rgba(255, 255, 255, 0.72);
        font-size: 14px;
        line-height: 1.7;
    }
}

/* =========================================
   4. RIGHT SECTION & FLIP CARD
   ========================================= */

.nx-login-form-section {
    flex: 1;
    height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #182a3e;
    color: #ffffff;
    padding: 0 !important;
    perspective: 1200px;
}

.nx-flip-card {
    width: 100%;
    max-width: 520px;
    height: 600px;
}

.nx-flip-inner {
    position: relative;
    width: 100%;
    height: 100%;
    transition: transform 0.8s cubic-bezier(0.4, 0, 0.2, 1);
    transform-style: preserve-3d;
}

.nx-flip-card.nx-flipped .nx-flip-inner {
    transform: rotateY(180deg);
}

.nx-flip-face {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
}

.nx-flip-front {
    z-index: 2;
    transform: rotateY(0deg);
}

.nx-flip-back {
    transform: rotateY(180deg);
}

.nx-login-inner {
    width: 100%;
    padding: 30px 40px;
    box-sizing: border-box;
}

/* Headers & Messaging */
.nx-login-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 25px;
}

.nx-brand {
    color: #ffffff;
    font-size: 26px;
    font-weight: 800;
    letter-spacing: -0.5px;

    span {
        color: #f27457;
    }
}

.nx-external-link a {
    color: #f27457 !important;
    font-size: 12px;
    font-weight: 600;
    text-decoration: none;

    &:hover {
        text-decoration: underline;
    }
}

.nx-welcome {
    margin-bottom: 20px;

    .nx-kicker {
        display: block;
        margin-bottom: 6px;
        color: #f27457;
        font-size: 10px;
        font-weight: 700;
        letter-spacing: 1.5px;
    }

    h2 {
        margin: 0;
        color: #ffffff;
        font-size: 28px;
        font-weight: 750;
        line-height: 1.2;
    }

    p {
        margin: 6px 0 0;
        color: rgba(255, 255, 255, 0.58);
        font-size: 12px;
    }
}

/* =========================================
   5. STEPPER WIZARD (SIGN UP)
   ========================================= */

.nx-stepper {
    display: flex;
    align-items: center;
    margin-bottom: 20px;
}

.nx-step {
    display: flex;
    align-items: center;
    gap: 6px;
    cursor: pointer;
    opacity: 0.5;
    transition: opacity 0.2s ease;

    &.active, &.completed {
        opacity: 1;
    }

    .nx-step-number {
        width: 22px;
        height: 22px;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.15);
        color: #ffffff;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 11px;
        font-weight: 700;
    }

    &.active .nx-step-number {
        background: #f27457;
        color: #ffffff;
    }

    &.completed .nx-step-number {
        background: #10b981;
        color: #ffffff;
    }

    .nx-step-label {
        color: rgba(255, 255, 255, 0.9);
        font-size: 11px;
        font-weight: 600;
    }
}

.nx-step-line {
    flex: 1;
    height: 2px;
    background: rgba(255, 255, 255, 0.15);
    margin: 0 8px;

    &.active {
