    }
}

.nx-signup-slider {
    overflow: hidden;
    width: 100%;
}

.nx-signup-track {
    display: flex;
    width: 300%;
    transition: transform 0.35s ease-in-out;
}

.nx-signup-tab {
    width: 33.3333%;
    flex-shrink: 0;
    padding: 0 2px;
    box-sizing: border-box;
}

/* Standalone simple-role form (Placement Officer / HR) — NOT part of the
