    align-items: center;
    gap: 6px;
    min-height: 28px;
    padding: 4px 8px 4px 10px;

    background: rgba(242, 116, 87, 0.14);
    border: 1px solid rgba(242, 116, 87, 0.35);
    border-radius: 6px;

