    font-size: 10px;
}

.nx-skill-dropdown {
    position: absolute;

    top: calc(100% + 5px);
    left: 0;
    right: 0;

    z-index: 9999;

    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 8px;

    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);

    overflow: hidden;
}

.nx-skill-search {
    position: relative;
    padding: 8px;
    border-bottom: 1px solid #e5e7eb;
}

.nx-skill-search i {
    position: absolute;

    left: 17px;
    top: 50%;

    transform: translateY(-50%);

    color: #9ca3af;
    font-size: 11px;
}

