}

.nx-skill-empty {
    padding: 18px 12px;

    text-align: center;

    color: #9ca3af;
    font-size: 11px;
}

sp_widget.script:
(function() {
    options.show_panel = options.show_panel == "true" || options.show_panel == true;

    /* =========================================
       SKILL CATALOG
       ========================================= */

    data.skill_catalog = [];

    var skillCatalog = new GlideRecord('x_snc_college_pl_0_skills_catalog');

    if (skillCatalog.isValid()) {
        skillCatalog.query();

        while (skillCatalog.next()) {

            var skillName = '';

            if (skillCatalog.isValidField('skill_name') &&
                skillCatalog.getValue('skill_name')) {

                skillName = skillCatalog.getValue('skill_name');

            } else if (skillCatalog.isValidField('name') &&
                       skillCatalog.getValue('name')) {

                skillName = skillCatalog.getValue('name');

            } else if (skillCatalog.isValidField('skill') &&
                       skillCatalog.getValue('skill')) {

                skillName = skillCatalog.getValue('skill');
            }

            if (skillName) {
                data.skill_catalog.push({
                    sys_id: skillCatalog.getUniqueValue(),
                    name: skillName
                });
            }
        }
    }


    /* =========================================
       1. SIGNUP / MULTI-ROLE REGISTRATION HANDLER
       ========================================= */

    if (input && input.action === "signup_student") {

        data.signupSuccess = false;
        data.signupError = "";

        if (!input.signupForm) {
            data.signupError = gs.getMessage("Invalid registration payload.");
            return;
        }

        var form = input.signupForm;
        var role = form.role;

        var ROLE_NAME_MAP = {
            'student': 'x_snc_college_pl_0.student_user',
            'coordinator': 'x_snc_college_pl_0.placement_officer',
            'placement_officer': 'x_snc_college_pl_0.placement_admin',
            'hr': 'x_snc_college_pl_0.interviewer'
        };

        if (!role || !ROLE_NAME_MAP[role]) {
            data.signupError = gs.getMessage("Please select a valid role.");
            return;
        }

        var isFullProfileRole = (role === 'student' || role === 'coordinator');

        if (!form.studentName || !form.email || !form.password || !form.confirmPassword) {
            data.signupError = gs.getMessage("Please fill in all required fields.");
            return;
        }

        if (form.password !== form.confirmPassword) {
            data.signupError = gs.getMessage("Password and Confirm Password do not match.");
            return;
        }

        var strongPwd = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W_]).{8,}$/;

        if (!strongPwd.test(form.password)) {
            data.signupError = gs.getMessage("Password must be 8+ characters with uppercase, lowercase, a number, and a special character.");
            return;
        }

        if (isFullProfileRole) {

            if (!form.registerNumber ||
                !form.mobile ||
                !form.collegeName ||
                !form.branch ||
                form.cgpa === '' ||
                form.passingYear === '' ||
                form.backlogs === '' ||
                !form.skills) {

                data.signupError = gs.getMessage("Please fill in all required fields marked with *.");
                return;
            }
        }

        try {

            var nameParts = form.studentName.trim().split(" ");

            var firstName = nameParts[0] || "";
            var lastName = nameParts.length > 1 ?
                nameParts.slice(1).join(" ") :
                "";

            var regUtil =
                new x_snc_college_pl_0.NexoraRegistrationUtil();

            var userResult =
                regUtil.registerUser({

                    email: form.email,

                    firstName: firstName,

                    lastName: lastName,

                    phone: form.mobile || '',

                    password: form.password,

                    roleName: ROLE_NAME_MAP[role],

                    registerNumber: form.registerNumber,

                    gender: form.gender,

                    collegeName: form.collegeName,

                    branch: form.branch,

                    cgpa: form.cgpa,

                    passingYear: form.passingYear,

                    backlogs: form.backlogs,

                    skills: form.skills,

                    git: form.git,

                    linkedin: form.linkedin
                });

            if (!userResult.success) {

                data.signupError =
                    userResult.error ||
                    gs.getMessage("Failed to create account.");

                return;
            }

            data.signupSuccess = true;

            if (userResult.requestId) {

                // Coordinator / Placement Officer / HR — waiting on approval
                data.pendingApproval = true;

                data.signupSuccessMessage =
                    userResult.message;

            } else {

                // Student — immediate access
                data.signupSuccessMessage =
                    userResult.message;

                data.redirectUrl =
                    "/nexora?id=dashboard";
            }

        } catch (ex) {

            gs.error(
                "Nexora Registration Error: " +
                ex.message
            );

            data.signupError =
                gs.getMessage(
                    "Server Exception during registration: "
                ) + ex.message;
        }

        return;
    }


    /* =========================================
       2. ORIGINAL SERVICENOW LOGIN & SSO LOGIC
       ========================================= */

    if (input && input.action === "multi_factor_auth_setup") {

        if (gs.getSession().getProperty("setup_multifactor_authn")) {

            if (input.directTo &&
                input.directTo != "/login_cpw.do") {

                gs.getSession().putProperty(
                    "nav_to",
                    input.directTo
                );

                gs.getSession().putProperty(
                    "starting_page",
                    input.directTo
                );
            }

            gs.getSession().putProperty(
                "is_direct_redirect",
                "true"
            );
        }

        return;
    }

    var portalRecord = $sp.getPortalRecord();

    var idpList = [];

    data.isMultiSSOActive =
        gs.getProperty(
            'glide.authenticate.multisso.enabled',
            'false'
        ) == 'true';

    if (data.isMultiSSOActive) {

        data.portal_authentication_mode =
            $sp.getValue(
                "enable_portal_authentication"
            ) == 'true';

        data.use_local_login =
            $sp.getValue(
                "enable_local_login"
            ) == 'true';

        var portalIdentityProviders =
            $sp.getValue(
                'portal_identity_providers'
            );

        if (
            data.portal_authentication_mode &&
            portalIdentityProviders
        ) {

            var arr =
                portalIdentityProviders.split(',');

            for (var i = 0; i < arr.length; i++) {

                var val = arr[i];

                if (val)
                    idpList.push(
                        val.trim() + ""
                    );
            }
        }
    }

    var ssoSelectorField =
        gs.getProperty(
            'glide.authenticate.multisso.login_locate.user_field',
            'user_name'
        );

    var grUser =
        new GlideRecord('sys_user');

    data.ssoSelectorFieldLabel =
        grUser
            .getElement(ssoSelectorField)
            .getED()
            .getLabel();

    if (
        input &&
        input.action === "set_sso_destination"
    ) {

        var gs_nav_to =
            gs.getSession().getProperty("nav_to");

        gs.getSession().putProperty(
            "nav_to",
            null
        );

        if (input.pageURI) {

            gs.getSession().putProperty(
                "is_direct_redirect",
                "true"
            );

            gs.getSession().putProperty(
                "starting_page",
                input.pageURI
            );

        } else if (
            !gs.getSession().getProperty(
                "starting_page"
            ) &&
            gs_nav_to
        ) {

            gs.getSession().putProperty(
                "starting_page",
                gs_nav_to
            );
        }

        return;
    }

    var self_registration_field =
        portalRecord ?
        portalRecord.getValue(
            "user_registration_config"
        ) :
        "";

    if (self_registration_field) {

        var registration_config =
            new GlideRecord(
                "sys_user_registration_config"
            );

        registration_config.addActiveQuery();

        registration_config.query(
            'sys_id',
            self_registration_field
        );

        if (registration_config.next()) {

            var self_registration_record_producer =
                registration_config.getValue(
                    "record_producer"
                );

            var self_registration_label =
                registration_config.getDisplayValue(
                    "registration_label"
                ) ||
                gs.getMessage("Sign Up");

            data.self_registration_record_producer =
                self_registration_record_producer;

            data.self_registration_label =
                self_registration_label;
        }
    }

    if (
        portalRecord &&
        (
            portalRecord.getValue(
                'enable_certificate_based_authentication'
            ) == 1
        )
    ) {

        data.cert_based_auth =
            gs.getProperty(
                'glide.authenticate.mutual.enabled',
                'false'
            ) == 'true';
    }

    if (data.cert_based_auth) {

        var request =
            GlideTransaction
                .get()
                .getRequest();

        var certHeader =
            request.getHeader(
                "X-Client-Cert"
            );

        if (!certHeader) {

            data.certHeader = "false";

            gs.log(
                "Failed to register PIV/CAC certificate to the user account."
            );

        } else {

            data.certHeader = "true";
        }
    }

    data.isShowLoginWithIdps = false;

    data.isMultiSSOActive =
        gs.getProperty(
            'glide.authenticate.multisso.enabled',
            'false'
        ) == 'true';

    var ssoRecords = [];

    data.ssoRecords = [];

    var gr =
        new GlideRecord(
            "sso_properties"
        );

    if (
        data.isMultiSSOActive &&
        gr.isValid()
    ) {

        ssoRecords =
            new MultiSSO_OidcUtil()
                .getSSORecords();
    }

    if (!data.portal_authentication_mode) {

        data.ssoRecords =
            ssoRecords;

    } else if (idpList.length > 0) {

        for (
            var j = 0;
            j < ssoRecords.length;
            j++
        ) {

            var idp =
                ssoRecords[j];

            if (
                idpList.indexOf(
                    idp.sysId.trim()
                ) !== -1
            ) {

                data.ssoRecords.push(
                    idp
                );
            }
        }
    }

    data.isShowLoginWithIdps =
        (data.ssoRecords.length > 0);

    data.pswdResetUrl =
        gs.getProperty(
            'glide.security.password_reset.uri'
        );

    data.forgotPwdLinkProp =
        gs.getProperty(
            'glide.security.forgot_password.display.link'
        );

    data.errorMsg =
        gs.getMessage(
            "There was an error processing your request"
        );

    data.errorMsg2 =
        gs.getMessage(
            "An error has occurred - please contact your system administrator"
        );

    data.passwordMsg =
        gs.getMessage("Password");

    data.usernameMsg =
        gs.getMessage("User name");

    data.forgetMe =
        GlideProperties.getBoolean(
            "glide.ui.forgetme"
        );

    data.rememberMeDefault =
        GlideProperties.getBoolean(
            'glide.ui.remember.me.default',
            true
        );

    data.is_logged_in =
        gs.getSession().isLoggedIn();

    var bypass_sso =
        options.bypass_sso == "true";

    data.multisso_enabled =
        !bypass_sso &&
        GlideProperties.getBoolean(
            "glide.authenticate.multisso.enabled"
        );

    data.default_idp =
        GlideProperties.get(
            "glide.authenticate.sso.redirect.idp"
        );

    data.pageURI =
        new GlideSPUtil().getPageUri();

    data.multiFactorAuthEnabled =
        GlideProperties.getBoolean(
            'glide.authenticate.multifactor',
            false
        );

    data.certAuthRedirect =
        gs.getProperty(
            'glide.authenticate.cert.redirect.enable',
            'false'
        ) == 'true';

    if (
        data.portal_authentication_mode &&
        data.use_local_login
    )
        data.default_idp = null;

    if (
        data.portal_authentication_mode &&
        data.ssoRecords.length > 0
    ) {

        if (data.ssoRecords.length == 1)

            data.default_idp =
                data.ssoRecords[0].sysId;

        else if (data.ssoRecords.length > 1)

            data.default_idp = null;
    }

    var customURL =
        GlideProperties.getBoolean(
            'glide.customurl.enabled',
            false
        );

    if (
        customURL == true &&
        data.multisso_enabled == true
    ) {

        var idp =
            SNC.CustomURLSPUtil
                .getAutoRedirectIDPForCustomURLWithPortal();

        if (GlideStringUtil.notNil(idp))

            data.default_idp = idp;
    }

    var isSessionAccessReduced =
        GlideSession.get()
            .getBooleanProperty(
                "isSessionAccessReduced",
                false
            );

    var isSessionAccessMessageShown =
        GlideSession.get()
            .getBooleanProperty(
                "isSessionAccessReducedMessageShown",
                false
            );

    if (
        isSessionAccessReduced &&
        !isSessionAccessMessageShown
    )

        SNC.SessionAccessUtil
            .showUserInfoMessageIfAccessReduced();

})();
